33	    pub(crate) fn compute_announcement_info(&mut self, announcing: &AnnouncementTag) {
34	        // Default to using the tag as a title
35	        self.manifest.announcement_title = Some(announcing.tag.clone());
36	        self.manifest.announcement_tag = Some(announcing.tag.clone());
37	        self.manifest.announcement_is_prerelease = announcing.prerelease;
38	
39	        // Refine the answers
40	        self.compute_announcement_changelog(announcing);
41	        self.compute_announcement_github();
42	    }
