44	    /// Try to compute changelogs for the announcement
45	    pub fn compute_announcement_changelog(&mut self, announcing: &AnnouncementTag) {
46	        let info = if let Some(announcing_version) = &announcing.version {
47	            // Try to find the version we're announcing in the top level CHANGELOG/RELEASES
48	            let version = axoproject::Version::Cargo(announcing_version.clone());
49	            let Ok(Some(info)) = self.workspace.changelog_for_version(&version) else {
50	                info!(
51	                    "failed to find {version} in workspace changelogs, skipping changelog generation"
52	                );
53	                return;
54	            };
55	
56	            info
57	        } else if let Some(announcing_package) = announcing.package {
58	            // Try to find the package's specific CHANGELOG/RELEASES
59	            let package = self.workspace.package(announcing_package);
60	            let package_name = &package.name;
61	            let version = package
62	                .version
63	                .as_ref()
64	                .expect("cargo package without a version!?");
65	            let Ok(Some(info)) = self
66	                .workspace
67	                .package(announcing_package)
68	                .changelog_for_version(version)
69	            else {
70	                info!(
71	                    "failed to find {version} in {package_name} changelogs, skipping changelog generation"
72	                );
73	                return;
74	            };
75	
76	            info
77	        } else {
78	            unreachable!("you're neither announcing a version or a package!?");
79	        };
80	
81	        info!("successfully parsed changelog!");
82	        self.manifest.announcement_title = Some(info.title);
83	        // Those windows newlines get everywhere...
84	        let clean_notes = newline_converter::dos2unix(&info.body);
85	        self.manifest.announcement_changelog = Some(clean_notes.into_owned());
86	    }
87	
88	    /// If we're publishing to Github, generate some Github notes
89	    fn compute_announcement_github(&mut self) {
90	        announcement_github(&mut self.manifest);
91	    }
