151	/// Parse the announcement tag and determine what we're announcing
152	///
153	/// `tag` being None here is equivalent to `--tag` not being passed, and tells us to infer
154	/// the tag based on things like "every package has the same version, assume we're
155	/// announcing that version".
156	///
157	/// `needs_coherent_announcement_tag = false` tells us to produce a result even if inference
158	/// fails to find a tag that will unambiguously work. This is used by commands like `init`
159	/// and `generate` which want to consider "everything" even if the user never actually
160	/// could announce everything at once. In this case dummy values will appear in every field
161	/// except for `AnnouncementTag::rust_releases` which will contain every distable binary
162	/// in the workspace.
163	pub(crate) fn select_tag(
164	    graph: &DistGraphBuilder,
165	    tag: Option<&str>,
166	    needs_coherent_announcement_tag: bool,
167	) -> DistResult<AnnouncementTag> {
168	    let packages: Vec<Package> = graph
169	        .workspace()
170	        .packages()
171	        .map(|(_, info)| Package {
172	            name: info.name.clone(),
173	            version: info.version.clone().map(|v| v.semver().clone()),
174	        })
175	        .collect();
176	
177	    // Parse the tag
178	    let mut announcing = if let Some(tag) = tag {
179	        parse_tag(&packages, tag)?
180	    } else {
181	        PartialAnnouncementTag::default()
182	    };
183	    // Select which packages/binaries are available from that tag
184	    let rust_releases = select_packages(graph, &announcing);
185	
186	    // Don't proceed if the conclusions don't make sense
187	    if rust_releases.is_empty() {
188	        // No binaries were selected, and they weren't trying to announce a library,
189	        // we've gotta bail out, this is too weird.
190	        //
191	        // To get better help messages, we explore a hypothetical world where they didn't pass
192	        // `--tag` so we can get all the options for a good help message.
193	        let announcing = PartialAnnouncementTag::default();
194	        let rust_releases = select_packages(graph, &announcing);
195	        let versions = possible_tags(graph, rust_releases.iter().map(|(idx, _)| *idx));
196	        let help = tag_help(graph, versions, "You may need to pass the current version as --tag, or need to give all your packages the same version");
197	        return Err(DistError::NothingToRelease { help });
198	    }
199	
200	    // If we don't have a tag yet we MUST successfully select one here or fail
201	    if matches!(announcing.release, ReleaseType::None) {
202	        // Group distable packages by version, if there's only one then use that as the tag
203	        let versions = possible_tags(graph, rust_releases.iter().map(|(idx, _)| *idx));
204	        if versions.len() == 1 {
205	            // Nice, one version, use it
206	            let version = *versions.first_key_value().unwrap().0;
207	            let tag = format!("v{version}");
208	            info!("inferred Announcement tag: {}", tag);
209	            announcing.tag = tag;
210	            announcing.prerelease = !version.pre.is_empty();
211	            announcing.release = ReleaseType::Version(version.clone());
212	        } else if needs_coherent_announcement_tag {
213	            // More than one version, give the user some suggestions
214	            let help = tag_help(
215	                graph,
216	                versions,
217	                "Please either specify --tag, or give them all the same version",
218	            );
219	            return Err(DistError::TooManyUnrelatedApps { help });
220	        } else {
221	            // Ok we got more than one version but we're being run by a command
222	            // like `init` or `generate` which just wants us to hand it everything
223	            // and doesn't care about coherent announcements. So use a fake tag
224	            // and hand it the fully unconstrained list of rust_releases.
225	            announcing.tag = "v1.0.0-FAKEVER".to_owned();
226	            announcing.prerelease = true;
227	            announcing.release = ReleaseType::Version("1.0.0-FAKEVER".parse().unwrap());
228	        }
229	    }
230	
231	    let mut version = None;
232	    let mut package = None;
233	    match &announcing.release {
234	        ReleaseType::Package(id) => package = Some(PackageIdx(*id)),
235	        ReleaseType::Version(ver) => version = Some(ver.clone()),
236	        ReleaseType::None => {}
237	    }
238	
239	    Ok(AnnouncementTag {
240	        tag: announcing.tag,
241	        version,
242	        package,
243	        prerelease: announcing.prerelease,
244	        rust_releases,
245	    })
246	}
